"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[9459],{99459:a=>{a.exports=JSON.parse('{"slug":"samolet-tekhdefolt-reyting-gendirektor","locale":"ru","title":"Застройщик \xabСамолет\xbb за месяц задержал выплату по облигациям, получил 2 понижения рейтинга и лишился гендиректора","description":"\xabСамолет\xbb допустил техдефолт, 2 агентства снизили рейтинг до BBB, гендиректор уходит после санкций ЕС. Что это значит для покупателей и инвесторов.","blocks":[{"id":"b001","kind":"paragraph","text":"В конце сентября 2026 года группа \xabСамолет\xbb на один день задержала погашение выпуска облигаций на 2,5 млрд рублей и объяснила это задержкой перечисления платежа. Такую задержку называют техническим дефолтом: деньги у компании есть, но платёж не дошёл вовремя. После этого рейтинговое агентство АКРА снизило кредитный рейтинг \xabСамолета\xbb до BBB с негативным прогнозом, а 15 октября то же сделало НКР, опустив рейтинг с A."},{"id":"b002","kind":"paragraph","text":"Кредитный рейтинг показывает, насколько вероятно, что компания вернёт долги. Это как кредитная история человека: чем она хуже, тем выше процент по новому займу. НКР объяснило понижение ростом долговой нагрузки, ослаблением показателей обслуживания долга и снижением рентабельности. Негативный прогноз агентство связало с ужесточением условий ипотечных программ: когда ипотека дорожает, квартиры продаются хуже, и застройщику труднее платить по долгам."},{"id":"b003","kind":"paragraph","text":"В середине октября ЕС ввёл санкции против \xabСамолета\xbb и его гендиректора Анны Акиньшиной. Поводом назвали работников из КНДР на стройках во Владивостоке, что ЕС считает нарушением санкций ООН 2017 года. 16 октября компания сообщила, что Акиньшина уходит по личным причинам. На её место предложат Ивана Иванова, который руководит направлением \xabСамолет селект\xbb. Ещё 2 члена совета директоров сложили полномочия, их имена не раскрыли."},{"id":"b004","kind":"paragraph","text":"Главный кредитор \xabСамолета\xbb — Сбербанк, его кредитный портфель в компании 274,2 млрд рублей. Первый зампред правления Сбербанка Александр Ведяхин заявил, что банк работает со всеми кредиторами застройщика и готовит план улучшения ситуации. 9 октября Министерство строительства собрало застройщиков, банки и налоговую службу и потребовало от банков мобилизовать ресурсы, чтобы крупный застройщик достроил все дома. Название компании в сообщении министерства не прозвучало."},{"id":"b005","kind":"paragraph","text":"Проблемы не начались в октябре. Ещё в начале 2026 года \xabСамолет\xbb просил у правительства льготный кредит на 48–50 млрд рублей, но подкомиссия Министерства финансов не нашла у него критических проблем. Акции, которые на IPO продавали по 950 рублей, в июле после отказа от дивидендов упали ниже 300 рублей, а 16 октября стоили около 247,6 рубля, почти в 4 раза дешевле. \xabСамолет\xbb при этом не исключение: по данным \xabЭксперт РА\xbb, за 9 месяцев 2026 года понижения составили 8,1% рейтинговых действий агентства по компаниям реального сектора с высоким рейтингом против 1,8% за весь 2025 год."},{"id":"b006","kind":"paragraph","text":"Для покупателей квартир главный вопрос, будут ли достроены дома. Минстрой требует от банков именно этого, а главный кредитор сам готовит план, поэтому позиция властей и банка пока на стороне достройки. Для держателей облигаций понижение рейтинга означает, что бумаги стали рискованнее, и рынок требует за этот риск больше процентов. Держать их дальше значит ставить на план Сбербанка, продавать сейчас значит зафиксировать убыток по сниженной цене. Каким будет план и успеет ли он до следующих выплат, пока неизвестно."},{"id":"b007","kind":"heading","text":"Что случилось с застройщиком \xabСамолет\xbb?"},{"id":"b008","kind":"paragraph","text":"В конце сентября 2026 года компания на день задержала погашение облигаций на 2,5 млрд рублей. После этого АКРА и НКР снизили её рейтинг до BBB с негативным прогнозом, ЕС ввёл санкции против компании и гендиректора, а гендиректор Анна Акиньшина объявила об уходе."},{"id":"b009","kind":"heading","text":"Что такое технический дефолт?"},{"id":"b010","kind":"paragraph","text":"Это задержка выплаты по долгу на несколько дней, когда деньги у компании есть, но платёж не дошёл вовремя. У \xabСамолета\xbb задержка длилась один день, компания объяснила её задержкой перечисления. Для рынка это всё равно сигнал: денег на выплаты впритык."},{"id":"b011","kind":"heading","text":"Что будет с домами \xabСамолета\xbb?"},{"id":"b012","kind":"paragraph","text":"9 октября Минстрой потребовал от банков мобилизовать ресурсы, чтобы застройщики достроили дома и выполнили обязательства перед покупателями. Сбербанк, крупнейший кредитор \xabСамолета\xbb, готовит план улучшения ситуации. Каким он будет, пока не объявлено."}],"sources":[{"label":"Сколько дефолтов случилось на российском долговом рынке с 12 по 16 октября","url":"https://frankmedia.ru/310263"},{"label":"Девелопер \xabСамолет\xbb объявил о смене генерального директора","url":"https://frankmedia.ru/310548"},{"label":"НКР снизило рейтинг \xabСамолета\xbb до BBB вслед за АКРА","url":"https://frankmedia.ru/310395"},{"label":"Попавший под санкции российский застройщик объявил о смене гендиректора","url":"https://lenta.ru/news/2026/10/16/popavvshiy-pod-sanktsii-rossiyskiy-zastroyschik-ob-yavil-o-smene-gendirektora"},{"label":"Власти потребовали от российских банков мобилизовать поддержку застройщиков","url":"https://lenta.ru/news/2026/10/09/mobilizovat"}],"sourceBodySha256":"556c692bc853437d88a15a7dc68acf4d7948a9d61dd5f274aba150be3640471e"}')}}]);